-- Phase 8 — Penalties & Bonuses (SPEC §4 "Money", §5.4, R2).
--
-- One enum and one table. Everything else this phase needs already exists:
-- `LedgerEntry` carries PENALTY, BONUS and REVERSAL rows, `isAutoGenerated`
-- separates the engine's writes from a manager's, and the unique index on
-- `reversesEntryId` is what makes "reverse twice" impossible for two concurrent
-- recomputations rather than only for two careful ones.
--
-- Written by hand rather than generated. `prisma migrate dev` diffs the schema
-- against a shadow database and does not know about the four objects Phase 7
-- created in raw SQL (two append-only triggers, three partial unique indexes) —
-- the note at the bottom of `schema.prisma` says so. Generating this file would
-- have proposed dropping the ones Prisma *can* see.

-- CreateEnum
CREATE TYPE "PenaltyMode" AS ENUM ('FIXED_PER_DAY', 'PCT_TASK_VALUE_PER_DAY', 'PCT_DAILY_RATE_PER_DAY', 'FIXED_ONCE', 'PCT_TASK_VALUE_ONCE');

-- CreateTable
CREATE TABLE "penalty_profiles" (
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "mode" "PenaltyMode" NOT NULL,
    "value" DECIMAL(12,2) NOT NULL,
    "graceHours" INTEGER,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    "deletedAt" TIMESTAMP(3),

    CONSTRAINT "penalty_profiles_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "penalty_profiles_deletedAt_idx" ON "penalty_profiles"("deletedAt");

-- CreateIndex
CREATE INDEX "users_penaltyProfileId_idx" ON "users"("penaltyProfileId");

-- AddForeignKey
--
-- `ON DELETE SET NULL`, matching every other optional relation on `users`. A
-- profile is soft-deleted in practice (`deletedAt`), and the service detaches
-- its members explicitly so that the deduction they get next is the agency
-- default rather than a formula nobody can find in the UI any more.
ALTER TABLE "users" ADD CONSTRAINT "users_penaltyProfileId_fkey" FOREIGN KEY ("penaltyProfileId") REFERENCES "penalty_profiles"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- ─────────────────────────────────────────────────────────────────────────
-- No partial unique index for "exactly one active auto PENALTY per task"
-- (SPEC §5.4), and the absence is deliberate.
--
-- The rule is not "one PENALTY row per task": recomputation inserts a REVERSAL
-- and then a fresh PENALTY, so a task that went overdue for a week carries a
-- dozen PENALTY rows and exactly one of them is unreversed. "Unreversed"
-- depends on the *absence of another row*, which no unique index can express.
-- SPEC T4 adds a second legitimate survivor: after a revision, the original
-- delivery's penalty is frozen and stands alongside the revision's live one.
--
-- What serialises concurrent recomputations instead:
--
--  1. `ledger_entries_reversesEntryId_key` (Phase 7). Two racing recomputations
--     both try to reverse the same active entry; exactly one succeeds and the
--     other fails with a unique violation rather than double-reversing.
--  2. A per-task transaction advisory lock taken by
--     `modules/penalty/service.ts` before it reads, so the "no active entry
--     yet" case — where there is nothing to collide on — cannot produce two
--     first penalties.
--
-- Both are tested in tests/integration/penalty/concurrency.test.ts.
-- ─────────────────────────────────────────────────────────────────────────
